const MESES_ABREV = ["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];

const STORAGE_KEY = "atendimentos-records-v1";
const LOG_KEY = "atendimentos-import-log-v1";

function monthKeyFromDT(dt) {
  if (!dt || typeof dt !== "string") return null;
  const m = dt.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (!m) return null;
  return `${m[3]}-${m[2]}`;
}
function monthLabel(key) {
  if (!key) return "";
  const [y, m] = key.split("-");
  return `${MESES_ABREV[parseInt(m, 10) - 1]}/${y.slice(2)}`;
}
function parseBRDateTimeToMinutes(dt) {
  if (!dt || typeof dt !== "string") return null;
  const m = dt.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
  if (!m) return null;
  const [, d, mo, y, hh, mm] = m;
  return Date.UTC(+y, +mo - 1, +d, +hh, +mm) / 60000;
}
function fmtInt(v) {
  return new Intl.NumberFormat("pt-BR").format(v || 0);
}
function fmtPct(v) {
  if (!isFinite(v)) return "—";
  return new Intl.NumberFormat("pt-BR", { style: "percent", maximumFractionDigits: 1 }).format(v);
}
function fmtHoras(v) {
  if (v === null || v === undefined || !isFinite(v)) return "—";
  return `${new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 1 }).format(v)}h`;
}

const HEADER_MAP = {
  protocolo: "p", data_cadastro: "da", data_fechamento: "df", usuario_abertura: "ua",
  usuario_fechamento: "uf", motivo_fechamento: "m", status_fechamento: "sf", status: "s",
  quantidade_os: "qos",
};

function parseWorkbookToRecords(workbook) {
  const sheetName = workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: false, defval: "" });
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || "").trim().toLowerCase());
  const colIndex = {};
  headers.forEach((h, i) => { if (HEADER_MAP[h]) colIndex[HEADER_MAP[h]] = i; });
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || !row.length) continue;
    const protocolo = colIndex.p !== undefined ? row[colIndex.p] : null;
    if (!protocolo || protocolo === "-") continue;
    const uf = colIndex.uf !== undefined ? String(row[colIndex.uf] || "") : "";
    const ua = colIndex.ua !== undefined ? String(row[colIndex.ua] || "") : "";
    const atendente = uf && uf !== "N/A" && uf !== "-" ? uf : (ua && ua !== "-" ? ua : "-");
    const motivo = colIndex.m !== undefined ? String(row[colIndex.m] || "-") || "-" : "-";
    const status = colIndex.s !== undefined ? String(row[colIndex.s] || "-") || "-" : "-";
    const statusFechamento = colIndex.sf !== undefined ? String(row[colIndex.sf] || "-") || "-" : "-";
    const da = colIndex.da !== undefined ? String(row[colIndex.da] || "") || null : null;
    const df = colIndex.df !== undefined ? String(row[colIndex.df] || "") || null : null;
    let tempo = null;
    if (da && df && statusFechamento === "concluido") {
      const start = parseBRDateTimeToMinutes(da);
      const end = parseBRDateTimeToMinutes(df);
      if (start !== null && end !== null) {
        const h = (end - start) / 60;
        if (h >= 0 && h <= 24 * 30) tempo = Math.round(h * 100) / 100;
      }
    }
    const qosRaw = colIndex.qos !== undefined ? row[colIndex.qos] : null;
    const qos = qosRaw !== null && qosRaw !== "" && !isNaN(parseInt(qosRaw, 10)) ? parseInt(qosRaw, 10) : 0;
    out.push({ p: String(protocolo), a: atendente, m: motivo, s: status, sf: statusFechamento, da, df, t: tempo, qos });
  }
  return out;
}

function mergeRecords(existing, incoming) {
  const map = new Map(existing.map((r) => [r.p, r]));
  let added = 0, updated = 0;
  incoming.forEach((r) => {
    if (map.has(r.p)) updated++; else added++;
    map.set(r.p, r);
  });
  return { merged: Array.from(map.values()), added, updated };
}

function KpiCard({ icon: Icon, label, value, sub, accent }) {
  return (
    <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 20px", flex: "1 1 200px", minWidth: 190 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <div style={{ width: 28, height: 28, borderRadius: 7, background: accent + "1A", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Icon size={15} color={accent} strokeWidth={2.2} />
        </div>
        <span style={{ fontFamily: FONT_BODY, fontSize: 12.5, color: COLORS.inkMuted, fontWeight: 500 }}>{label}</span>
      </div>
      <div style={{ fontFamily: FONT_MONO, fontSize: 24, fontWeight: 600, color: COLORS.ink, letterSpacing: "-0.5px" }}>{value}</div>
      {sub && <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: COLORS.inkMuted, marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

function Toggle({ options, value, onChange }) {
  return (
    <div style={{ display: "inline-flex", background: COLORS.tealSoft, borderRadius: 8, padding: 3, gap: 2 }}>
      {options.map((opt) => (
        <button key={opt.value} onClick={() => onChange(opt.value)} style={{
          fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600, padding: "6px 14px", borderRadius: 6, border: "none",
          cursor: "pointer", background: value === opt.value ? COLORS.teal : "transparent",
          color: value === opt.value ? "#fff" : COLORS.tealDark, transition: "background 0.15s ease",
        }}>{opt.label}</button>
      ))}
    </div>
  );
}

function CheckboxPill({ label, checked, onClick, color }) {
  return (
    <button onClick={onClick} style={{
      display: "inline-flex", alignItems: "center", gap: 6, fontFamily: FONT_BODY, fontSize: 12.5,
      padding: "5px 10px 5px 8px", borderRadius: 7, cursor: "pointer",
      border: `1px solid ${checked ? (color || COLORS.teal) : COLORS.border}`,
      background: checked ? (color ? color + "14" : COLORS.tealSoft) : "#fff",
      color: checked ? COLORS.ink : COLORS.inkMuted, fontWeight: 500, transition: "all 0.12s ease",
    }}>
      <span style={{
        width: 14, height: 14, borderRadius: 4, border: `1.5px solid ${checked ? (color || COLORS.teal) : COLORS.borderStrong}`,
        background: checked ? (color || COLORS.teal) : "transparent", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      }}>
        {checked && <Check size={10} color="#fff" strokeWidth={3} />}
      </span>
      {label}
    </button>
  );
}

export default function AtendimentosDashboard() {
  const [records, setRecords] = useState(null);
  const [importLog, setImportLog] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploadMsg, setUploadMsg] = useState(null);
  const [uploadError, setUploadError] = useState(null);
  const [metric, setMetric] = useState("count");
  const [atendenteFilter, setAtendenteFilter] = useState(null);
  const [motivoFilter, setMotivoFilter] = useState(null);
  const [statusFilter, setStatusFilter] = useState(null);
  const [sortCol, setSortCol] = useState("total");
  const fileInputRef = useRef(null);

  useEffect(() => {
    (async () => {
      let recs = null, log = [];
      try {
        const res = await window.storage.get(STORAGE_KEY, false);
        if (res && res.value) recs = JSON.parse(res.value);
      } catch (e) { recs = null; }
      try {
        const res = await window.storage.get(LOG_KEY, false);
        if (res && res.value) log = JSON.parse(res.value);
      } catch (e) { log = []; }
      if (!recs) {
        recs = INITIAL_DATA;
        log = [{ date: "2026-09-04T00:00:00", label: "Base inicial", added: INITIAL_DATA.length, updated: 0 }];
        try {
          await window.storage.set(STORAGE_KEY, JSON.stringify(recs), false);
          await window.storage.set(LOG_KEY, JSON.stringify(log), false);
        } catch (e) { /* surfaced on next save attempt */ }
      }
      setRecords(recs);
      setImportLog(log);
      setLoading(false);
    })();
  }, []);

  const atendentes = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.a))).filter((v) => v && v !== "-").sort();
  }, [records]);
  const motivos = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.m))).filter((v) => v && v !== "-").sort();
  }, [records]);
  const statuses = useMemo(() => {
    if (!records) return [];
    return Array.from(new Set(records.map((r) => r.s))).filter((v) => v && v !== "-").sort();
  }, [records]);

  useEffect(() => { if (atendentes.length && !atendenteFilter) setAtendenteFilter(new Set(atendentes)); }, [atendentes]);
  useEffect(() => { if (motivos.length && !motivoFilter) setMotivoFilter(new Set(motivos)); }, [motivos]);
  useEffect(() => { if (statuses.length && !statusFilter) setStatusFilter(new Set(statuses)); }, [statuses]);

  const filtered = useMemo(() => {
    if (!records || !atendenteFilter || !motivoFilter || !statusFilter) return [];
    return records.filter((r) => atendenteFilter.has(r.a) && motivoFilter.has(r.m) && statusFilter.has(r.s) && monthKeyFromDT(r.da));
  }, [records, atendenteFilter, motivoFilter, statusFilter]);

  const months = useMemo(() => {
    const set = new Set(filtered.map((r) => monthKeyFromDT(r.da)));
    return Array.from(set).sort();
  }, [filtered]);

  const monthlyTotals = useMemo(() => {
    const map = new Map();
    months.forEach((m) => map.set(m, { month: m, count: 0, resolvidos: 0, tempoSum: 0, tempoCount: 0, semVisita: 0 }));
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.da);
      const e = map.get(mk);
      if (!e) return;
      e.count += 1;
      if (r.s === "Resolvido") e.resolvidos += 1;
      if (r.t !== null && r.t !== undefined) { e.tempoSum += r.t; e.tempoCount += 1; }
      if (!r.qos) e.semVisita += 1;
    });
    return months.map((m) => {
      const e = map.get(m);
      return { ...e, taxaResolucao: e.count ? e.resolvidos / e.count : 0, tempoMedio: e.tempoCount ? e.tempoSum / e.tempoCount : null, taxaSemVisita: e.count ? e.semVisita / e.count : 0 };
    });
  }, [filtered, months]);

  const atendenteMonthMatrix = useMemo(() => {
    const aSet = new Set(filtered.map((r) => r.a));
    const aList = Array.from(aSet).sort();
    const data = {};
    aList.forEach((a) => {
      data[a] = { atendente: a, totalCount: 0, totalTempoSum: 0, totalTempoCount: 0, byMonth: {} };
      months.forEach((m) => { data[a].byMonth[m] = { count: 0, tempoSum: 0, tempoCount: 0 }; });
    });
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.da);
      if (!data[r.a]) return;
      data[r.a].byMonth[mk].count += 1;
      data[r.a].totalCount += 1;
      if (r.t !== null && r.t !== undefined) {
        data[r.a].byMonth[mk].tempoSum += r.t; data[r.a].byMonth[mk].tempoCount += 1;
        data[r.a].totalTempoSum += r.t; data[r.a].totalTempoCount += 1;
      }
    });
    let rows = Object.values(data);
    const cellMetric = (row, m) => {
      const c = row.byMonth[m];
      return metric === "count" ? c.count : (c.tempoCount ? c.tempoSum / c.tempoCount : null);
    };
    const totalMetric = (row) => metric === "count" ? row.totalCount : (row.totalTempoCount ? row.totalTempoSum / row.totalTempoCount : null);
    rows.sort((a, b) => {
      if (sortCol === "atendente") return a.atendente.localeCompare(b.atendente);
      if (sortCol === "total") return (totalMetric(b) || 0) - (totalMetric(a) || 0);
      return (cellMetric(b, sortCol) || 0) - (cellMetric(a, sortCol) || 0);
    });
    return rows;
  }, [filtered, months, sortCol, metric]);

  const motivoMonthMatrix = useMemo(() => {
    const mSet = new Set(filtered.map((r) => r.m));
    const mList = Array.from(mSet).sort((a, b) => {
      const ca = filtered.filter((r) => r.m === a).length;
      const cb = filtered.filter((r) => r.m === b).length;
      return cb - ca;
    });
    const data = {};
    mList.forEach((mo) => {
      data[mo] = { motivo: mo, totalCount: 0, byMonth: {} };
      months.forEach((m) => { data[mo].byMonth[m] = 0; });
    });
    filtered.forEach((r) => {
      const mk = monthKeyFromDT(r.da);
      if (!data[r.m]) return;
      data[r.m].byMonth[mk] += 1;
      data[r.m].totalCount += 1;
    });
    return Object.values(data);
  }, [filtered, months]);

  const kpis = useMemo(() => {
    if (!months.length) return null;
    const currentMonth = months[months.length - 1];
    const curEntry = monthlyTotals.find((m) => m.month === currentMonth) || { count: 0, taxaResolucao: 0, taxaSemVisita: 0 };
    const tempos = filtered.filter((r) => r.t !== null && r.t !== undefined).map((r) => r.t);
    const tempoMedio = tempos.length ? tempos.reduce((s, v) => s + v, 0) / tempos.length : null;
    const porAtendente = {};
    filtered.forEach((r) => { if (r.a !== "-") porAtendente[r.a] = (porAtendente[r.a] || 0) + 1; });
    const top = Object.entries(porAtendente).sort((a, b) => b[1] - a[1])[0];
    return { currentMonth, curCount: curEntry.count, taxaResolucao: curEntry.taxaResolucao, taxaSemVisita: curEntry.taxaSemVisita, tempoMedio, topAtendente: top ? top[0] : "—", topCount: top ? top[1] : 0 };
  }, [months, monthlyTotals, filtered]);

  const grandTotal = useMemo(() => {
    const count = filtered.length;
    const byMonth = {};
    months.forEach((m) => { byMonth[m] = monthlyTotals.find((x) => x.month === m) || { count: 0 }; });
    return { count, byMonth };
  }, [filtered, months, monthlyTotals]);

  const handleFile = useCallback(async (file) => {
    setUploadMsg(null); setUploadError(null);
    try {
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: "array" });
      const parsed = parseWorkbookToRecords(wb);
      if (!parsed.length) {
        setUploadError("Não encontrei linhas reconhecíveis nesse arquivo. Confira se é uma exportação do mesmo relatório de atendimentos.");
        return;
      }
      const { merged, added, updated } = mergeRecords(records || [], parsed);
      const newLog = [{ date: new Date().toISOString(), label: file.name, added, updated }, ...importLog].slice(0, 20);
      try {
        await window.storage.set(STORAGE_KEY, JSON.stringify(merged), false);
        await window.storage.set(LOG_KEY, JSON.stringify(newLog), false);
      } catch (e) {
        setUploadError("Não consegui salvar no banco (" + (e && e.message ? e.message : "erro desconhecido") + ").");
        return;
      }
      setRecords(merged);
      setImportLog(newLog);
      setUploadMsg(`Importado: ${added} novo(s), ${updated} atualizado(s).`);
    } catch (e) {
      setUploadError("Não consegui ler esse arquivo. Confira se é um .xlsx exportado do sistema.");
    }
  }, [records, importLog]);

  const handleReset = useCallback(async () => {
    if (!window.confirm("Isso vai apagar os relatórios importados e voltar para a base inicial. Continuar?")) return;
    const log = [{ date: "2026-09-04T00:00:00", label: "Base inicial", added: INITIAL_DATA.length, updated: 0 }];
    try {
      await window.storage.set(STORAGE_KEY, JSON.stringify(INITIAL_DATA), false);
      await window.storage.set(LOG_KEY, JSON.stringify(log), false);
    } catch (e) { setUploadError("Não consegui salvar no banco."); return; }
    setRecords(INITIAL_DATA);
    setImportLog(log);
  }, []);

  if (loading || !records) {
    return <div style={{ fontFamily: FONT_BODY, padding: 40, color: COLORS.inkMuted }}>Carregando painel…</div>;
  }

  const barData = monthlyTotals.map((m) => ({ ...m, label: monthLabel(m.month) }));

  return (
    <div style={{ fontFamily: FONT_BODY, color: COLORS.ink }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 16, marginBottom: 26 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
            <div style={{ width: 34, height: 34, borderRadius: 8, background: COLORS.teal, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
              <Headset size={18} color="#fff" strokeWidth={2.3} />
            </div>
            <h1 style={{ fontFamily: FONT_DISPLAY, fontSize: 22, fontWeight: 600, margin: 0, letterSpacing: "-0.3px" }}>Painel de atendimentos</h1>
          </div>
          <p style={{ fontFamily: FONT_BODY, fontSize: 13, color: COLORS.inkMuted, margin: 0 }}>
            {fmtInt(records.length)} atendimentos na base {importLog[0] ? `· atualizado em ${new Date(importLog[0].date).toLocaleDateString("pt-BR")}` : ""}
          </p>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <button onClick={handleReset} title="Restaurar base inicial" style={{
            display: "flex", alignItems: "center", gap: 6, fontFamily: FONT_BODY, fontSize: 12.5, fontWeight: 500,
            padding: "9px 12px", borderRadius: 8, border: `1px solid ${COLORS.border}`, background: "#fff", color: COLORS.inkMuted, cursor: "pointer",
          }}><RotateCcw size={13} /> Restaurar</button>
          <button onClick={() => fileInputRef.current && fileInputRef.current.click()} style={{
            display: "flex", alignItems: "center", gap: 7, fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600,
            padding: "9px 16px", borderRadius: 8, border: "none", background: COLORS.teal, color: "#fff", cursor: "pointer",
          }}><Upload size={14} /> Atualizar relatório</button>
          <input ref={fileInputRef} type="file" accept=".xlsx,.xls" style={{ display: "none" }}
            onChange={(e) => { const f = e.target.files && e.target.files[0]; if (f) handleFile(f); e.target.value = ""; }} />
        </div>
      </div>

      {(uploadMsg || uploadError) && (
        <div style={{
          marginBottom: 18, padding: "10px 14px", borderRadius: 8, fontSize: 13, fontFamily: FONT_BODY,
          background: uploadError ? COLORS.redSoft : COLORS.greenSoft, color: uploadError ? COLORS.red : COLORS.green,
          display: "flex", alignItems: "center", gap: 8,
        }}><Info size={14} /> {uploadError || uploadMsg}</div>
      )}

      {kpis && (
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 22 }}>
          <KpiCard icon={Headset} accent={COLORS.teal} label={`Atendimentos em ${monthLabel(kpis.currentMonth)}`} value={fmtInt(kpis.curCount)} sub="chamados abertos no mês mais recente" />
          <KpiCard icon={CheckCircle2} accent={COLORS.green} label="Taxa de resolução do mês" value={fmtPct(kpis.taxaResolucao)} sub="chamados com status Resolvido" />
          <KpiCard icon={Wrench} accent={COLORS.purple || COLORS.tealDark} label="Resolvido sem visita técnica" value={fmtPct(kpis.taxaSemVisita)} sub="chamados do mês que não geraram ordem de serviço" />
          <KpiCard icon={Clock} accent={COLORS.amber} label="Tempo médio de atendimento" value={fmtHoras(kpis.tempoMedio)} sub="da abertura até o fechamento, no filtro atual" />
          <KpiCard icon={Award} accent={COLORS.tealDark} label="Atendente mais atarefado" value={kpis.topAtendente} sub={`${fmtInt(kpis.topCount)} atendimentos no filtro atual`} />
        </div>
      )}

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "14px 16px", marginBottom: 22, display: "flex", flexWrap: "wrap", gap: 18, alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Atendente(s)</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 480 }}>
            {atendentes.map((v) => (
              <CheckboxPill key={v} label={v} checked={atendenteFilter && atendenteFilter.has(v)}
                onClick={() => setAtendenteFilter((prev) => { const next = new Set(prev); next.has(v) ? next.delete(v) : next.add(v); return next; })} />
            ))}
          </div>
        </div>
        <div style={{ width: 1, alignSelf: "stretch", background: COLORS.border }} />
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Status</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 320 }}>
            {statuses.map((s) => (
              <CheckboxPill key={s} label={s} checked={statusFilter && statusFilter.has(s)}
                color={s === "Resolvido" ? COLORS.green : s === "Pendente" ? COLORS.red : COLORS.amber}
                onClick={() => setStatusFilter((prev) => { const next = new Set(prev); next.has(s) ? next.delete(s) : next.add(s); return next; })} />
            ))}
          </div>
        </div>
        <div style={{ width: 1, alignSelf: "stretch", background: COLORS.border }} />
        <div>
          <div style={{ fontSize: 11.5, fontWeight: 600, color: COLORS.inkMuted, marginBottom: 7 }}>Tipo / motivo de fechamento</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, maxWidth: 480 }}>
            {motivos.map((m) => (
              <CheckboxPill key={m} label={m} checked={motivoFilter && motivoFilter.has(m)}
                onClick={() => setMotivoFilter((prev) => { const next = new Set(prev); next.has(m) ? next.delete(m) : next.add(m); return next; })} />
            ))}
          </div>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.1fr 1fr", gap: 16, marginBottom: 24 }}>
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 8px" }}>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Atendimentos por mês</div>
          <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 10 }}>Volume total, todos os meses da base</div>
          <ResponsiveContainer width="100%" height={230}>
            <BarChart data={barData} margin={{ top: 4, right: 8, left: -18, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
              <XAxis dataKey="label" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: COLORS.inkMuted }} axisLine={{ stroke: COLORS.border }} tickLine={false} />
              <YAxis tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip formatter={(v) => [fmtInt(v), "Atendimentos"]} contentStyle={{ fontFamily: FONT_BODY, fontSize: 12.5, borderRadius: 8, border: `1px solid ${COLORS.border}` }} />
              <Bar dataKey="count" fill={COLORS.teal} radius={[5, 5, 0, 0]} maxBarSize={44} />
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 8px" }}>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Taxa de resolução e tempo médio</div>
          <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 10 }}>% resolvido (linha) e horas médias por chamado, por mês</div>
          <ResponsiveContainer width="100%" height={230}>
            <LineChart data={barData} margin={{ top: 4, right: 8, left: -8, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.border} vertical={false} />
              <XAxis dataKey="label" tick={{ fontFamily: FONT_BODY, fontSize: 11, fill: COLORS.inkMuted }} axisLine={{ stroke: COLORS.border }} tickLine={false} />
              <YAxis yAxisId="pct" tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} tickFormatter={(v) => `${Math.round(v * 100)}%`} width={40} />
              <YAxis yAxisId="h" orientation="right" tick={{ fontFamily: FONT_MONO, fontSize: 11, fill: COLORS.inkMuted }} axisLine={false} tickLine={false} width={40} />
              <Tooltip formatter={(v, name) => name === "taxaResolucao" ? [fmtPct(v), "Taxa de resolução"] : [fmtHoras(v), "Tempo médio"]}
                contentStyle={{ fontFamily: FONT_BODY, fontSize: 12.5, borderRadius: 8, border: `1px solid ${COLORS.border}` }} />
              <Line yAxisId="pct" type="monotone" dataKey="taxaResolucao" stroke={COLORS.green} strokeWidth={2.4} dot={{ r: 3.5, fill: COLORS.green }} />
              <Line yAxisId="h" type="monotone" dataKey="tempoMedio" stroke={COLORS.amber} strokeWidth={2.4} dot={{ r: 3.5, fill: COLORS.amber }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 20px", marginBottom: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
          <div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600 }}>Atendente × mês</div>
            <div style={{ fontSize: 12, color: COLORS.inkMuted }}>Clique em uma coluna para ordenar</div>
          </div>
          <Toggle value={metric} onChange={setMetric} options={[{ value: "count", label: "Atendimentos" }, { value: "tempo", label: "Tempo médio" }]} />
        </div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: FONT_BODY, fontSize: 13, minWidth: 640 }}>
            <thead>
              <tr>
                <th onClick={() => setSortCol("atendente")} style={{ textAlign: "left", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>
                  Atendente <ArrowUpDown size={10} style={{ display: "inline", marginLeft: 2, verticalAlign: -1 }} />
                </th>
                {months.map((m) => (
                  <th key={m} onClick={() => setSortCol(m)} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>
                    {monthLabel(m)}
                  </th>
                ))}
                <th onClick={() => setSortCol("total")} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.ink, fontWeight: 700, fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}>Total</th>
              </tr>
            </thead>
            <tbody>
              {atendenteMonthMatrix.map((row, i) => (
                <tr key={row.atendente} style={{ background: i % 2 === 1 ? COLORS.bg : "transparent" }}>
                  <td style={{ padding: "8px 10px", fontWeight: 500, whiteSpace: "nowrap" }}>{row.atendente}</td>
                  {months.map((m) => {
                    const c = row.byMonth[m];
                    const val = metric === "count" ? c.count : (c.tempoCount ? c.tempoSum / c.tempoCount : null);
                    return (
                      <td key={m} style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, color: val ? COLORS.ink : COLORS.inkMuted }}>
                        {metric === "count" ? (val || "–") : fmtHoras(val)}
                      </td>
                    );
                  })}
                  <td style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 600, color: COLORS.tealDark }}>
                    {metric === "count" ? fmtInt(row.totalCount) : fmtHoras(row.totalTempoCount ? row.totalTempoSum / row.totalTempoCount : null)}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr>
                <td style={{ padding: "9px 10px", fontWeight: 700, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>Total</td>
                {months.map((m) => {
                  const e = grandTotal.byMonth[m] || { count: 0 };
                  return (
                    <td key={m} style={{ padding: "9px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 700, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>
                      {metric === "count" ? fmtInt(e.count) : fmtHoras(e.tempoMedio)}
                    </td>
                  );
                })}
                <td style={{ padding: "9px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 700, color: COLORS.tealDark, borderTop: `1.5px solid ${COLORS.borderStrong}` }}>
                  {metric === "count" ? fmtInt(grandTotal.count) : "—"}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "18px 18px 20px", marginBottom: 20 }}>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14.5, fontWeight: 600, marginBottom: 2 }}>Tipo / motivo × mês</div>
        <div style={{ fontSize: 12, color: COLORS.inkMuted, marginBottom: 14 }}>Quantidade de atendimentos por motivo de fechamento, mês a mês</div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: FONT_BODY, fontSize: 13, minWidth: 640 }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12 }}>Tipo / motivo</th>
                {months.map((m) => (
                  <th key={m} style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.inkMuted, fontWeight: 600, fontSize: 12, whiteSpace: "nowrap" }}>{monthLabel(m)}</th>
                ))}
                <th style={{ textAlign: "right", padding: "8px 10px", borderBottom: `1.5px solid ${COLORS.borderStrong}`, color: COLORS.ink, fontWeight: 700, fontSize: 12 }}>Total</th>
              </tr>
            </thead>
            <tbody>
              {motivoMonthMatrix.map((row, i) => (
                <tr key={row.motivo} style={{ background: i % 2 === 1 ? COLORS.bg : "transparent" }}>
                  <td style={{ padding: "8px 10px", fontWeight: 500 }}>{row.motivo}</td>
                  {months.map((m) => (
                    <td key={m} style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, color: row.byMonth[m] ? COLORS.ink : COLORS.inkMuted }}>
                      {row.byMonth[m] || "–"}
                    </td>
                  ))}
                  <td style={{ padding: "8px 10px", textAlign: "right", fontFamily: FONT_MONO, fontSize: 12.5, fontWeight: 600, color: COLORS.tealDark }}>{fmtInt(row.totalCount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {importLog.length > 0 && (
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "16px 18px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 10 }}>
            <History size={14} color={COLORS.inkMuted} />
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 13.5, fontWeight: 600 }}>Histórico de importações</div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {importLog.slice(0, 6).map((log, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, color: COLORS.inkSoft, padding: "4px 0" }}>
                <span style={{ fontWeight: 500 }}>{log.label}</span>
                <span style={{ color: COLORS.inkMuted }}>{new Date(log.date).toLocaleDateString("pt-BR")} · {log.added} novo(s), {log.updated} atualizado(s)</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <p style={{ fontSize: 11.5, color: COLORS.inkMuted, marginTop: 20, textAlign: "center" }}>
        "Tipo / motivo" usa o campo "motivo de fechamento" do relatório (não há uma coluna de tipo de atendimento separada).
        O atendente é quem fechou o chamado; quando não há um responsável pelo fechamento, usa-se quem abriu.
        "Resolvido sem visita técnica" usa o campo "quantidade_os" do relatório — chamados com quantidade_os igual a 0 não geraram ordem de serviço.
      </p>
    </div>
  );
}
